import { StatTile, CountRoll } from "march/ui"

// adım sayar: karoya her basış 500 adım ekler, sayı döner; 10.000'e varınca renk yeşile döner
export function StepCounter() {
  let $steps = 8500
  return <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
    <StatTile variant="card" size="xl" label="Bugünkü adım" hint={() => $steps >= 10000 ? "Hedef tamam! 🎉" : `Hedefe ${10000 - $steps} adım`}
      value={<CountRoll value={() => $steps} format="full" />} m:color={() => $steps >= 10000 ? "success" : "brand-orange"}
      onClick={() => $steps += 500} />
    <StatTile variant="tile" label="Kalori" value={() => Math.round($steps * 0.04)} hint="kcal" />
  </div>
}

import { StatTile, Card } from "march/ui"

// bir satış panelinin göstergeleri: önce etiket, sola hizalı kart karolar; biri rapora bağlantı, biri pasif
const KPIS = [
  { label: "Ciro", value: "₺248.300", hint: "geçen aya göre %12 ↑", color: "success" as const },
  { label: "Sipariş", value: "1.284", hint: "günde ortalama 41" },
  { label: "İade oranı", value: "%2,1", hint: "hedef %3'ün altında", color: "brand-blue" as const },
]

export function SalesKpis() {
  return <Card title="Kasım özeti">
    <div sx={{ grid: "fit", gap: 3 }}>
      {KPIS.map((k) => <StatTile variant="card" align="start" order="label" size="lg" label={k.label} value={k.value} hint={k.hint} m:color={k.color} />)}
      <StatTile variant="tile" align="start" order="label" label="Ayrıntılı rapor" value="Aç →" href="#rapor" />
      <StatTile variant="tile" align="start" order="label" label="Tahmin" value="Yakında" href="#tahmin" disabled />
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { StatTileLab } from "./StatTileLab.tsx"

// StatTileLab'in testleri: kaydedince Testler sekmesinde çalışır
test("onClick düğme yapar; basınca sayaç ve erişimci değer artar", async () => {
  const s = renderTest(() => <StatTileLab />)
  const b = s.get(".lab-btn")!
  expect(b.tagName).toBe("BUTTON")
  await s.click(b)
  await s.wait(400)
  expect(s.sees("80")).toBe(true)
})

test("href bağlantı yapar; disabled düğme basılamaz", () => {
  const s = renderTest(() => <StatTileLab />)
  expect(s.find("Rapor")!.closest("a")!.getAttribute("href")).toBe("#rapor")
  expect((s.find("Kapalı")!.closest("button") as HTMLButtonElement).disabled).toBe(true)
})

test("term dl içinde dt + dd çizer; partClass ve öznitelikler yazılır", () => {
  const s = renderTest(() => <StatTileLab />)
  const dl = s.get(".lab-dl")!
  expect(dl.querySelector("dt")!.classList.contains("lab-label")).toBe(true)
  expect(dl.querySelector("dd")!.classList.contains("lab-value")).toBe(true)
  expect(s.get("[data-kind=ayrıntı]")).not.toBe(null)
})
